function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100,000 values.';
  if (nums.some(v => v < 1 || v > 50)) return 'Each value of nums is between 1 and 50.';
  if (k < 1 || k > 50) return 'k is between 1 and 50.';
  return null;
}

