function maxFrequency(nums, k) {
  let original = 0;
  for (const num of nums) {
    if (num === k) {
      original++;
    }
  }
  const values = new Set(nums);
  let bestGain = 0;
  for (const target of values) {
    if (target === k) {
      continue;
    }
    let gain = 0;
    for (const num of nums) {
      if (num === target) {
        gain++;
      } else if (num === k) {
        gain--;
      }
      gain = Math.max(gain, 0);
      bestGain = Math.max(bestGain, gain);
    }
  }
  return original + bestGain;
}

