function maxFrequency(nums, k) {
  // Try every block and every shift that can matter, then count the k values directly.
  const n = nums.length;
  let best = 0;
  for (let i = 0; i < n; i++)
    for (let j = i; j < n; j++)
      for (let x = -50; x <= 50; x++) {
        let count = 0;
        for (let t = 0; t < n; t++) {
          const value = t >= i && t <= j ? nums[t] + x : nums[t];
          if (value === k) count++;
        }
        best = Math.max(best, count);
      }
  return best;
}

