function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(1, 10);
  // A handful of distinct values makes long interleaved runs; the full range spreads the values out.
  const top = rand() < 0.6 ? int(1, 4) : 50;
  const nums = Array.from({ length: n }, () => int(1, top));
  // k is usually a value that occurs in nums, sometimes one that may not.
  const k = rand() < 0.8 ? nums[int(0, n - 1)] : int(1, 50);
  return [nums, k];
}
